BEGIN TRANSACTION;
DROP TABLE IF EXISTS "alembic_version";
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
DROP TABLE IF EXISTS "catalog";
CREATE TABLE "catalog" (
	id INTEGER NOT NULL, 
	date_created DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, 
	date_archived DATETIME, 
	location TEXT, 
	label TEXT, 
	file_media TEXT, 
	file_media_nfo TEXT, 
	file_media_img TEXT, 
	path_media_rel TEXT, 
	path_media_sub TEXT, 
	path_media_img TEXT, 
	media_id INTEGER, 
	CONSTRAINT pk_catalog PRIMARY KEY (id), 
	CONSTRAINT uq_catalog_media_id UNIQUE (media_id)
);
DROP TABLE IF EXISTS "media";
CREATE TABLE "media" (
	id INTEGER NOT NULL, 
	type TEXT NOT NULL, 
	title TEXT NOT NULL, 
	year INTEGER, 
	duration INTEGER, 
	certificate TEXT, 
	genres TEXT, 
	description TEXT, 
	imdb_id TEXT, 
	tmdb_id TEXT, 
	catalog_id INTEGER, 
	user_id INTEGER NOT NULL, 
	wiki_id TEXT, 
	CONSTRAINT pk_media PRIMARY KEY (id), 
	CONSTRAINT uq_media_wiki_id UNIQUE (wiki_id), 
	CONSTRAINT uq_media_imdb_id UNIQUE (imdb_id), 
	CONSTRAINT uq_media_catalog_id UNIQUE (catalog_id), 
	CONSTRAINT uq_media_tmdb_id UNIQUE (tmdb_id), 
	CONSTRAINT uq_media_title UNIQUE (title), 
	CONSTRAINT fk_media_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
);
DROP TABLE IF EXISTS "users";
CREATE TABLE "users" (
	id INTEGER NOT NULL, 
	username TEXT NOT NULL, 
	password_hash TEXT DEFAULT ('') NOT NULL, 
	is_admin INTEGER DEFAULT '0' NOT NULL, 
	email TEXT NOT NULL, 
	phone TEXT, 
	date_created DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, role TEXT DEFAULT 'user' NOT NULL, 
	CONSTRAINT pk_users PRIMARY KEY (id), 
	CONSTRAINT uq_users_username UNIQUE (username), 
	CONSTRAINT uq_users_email UNIQUE (email)
);
COMMIT;
