INSERT INTO "media" ("id","type","title","year","duration","certificate","genres","description","imdb_id","tmdb_id","catalog_id","user_id","wiki_id") VALUES (1,'movie','The Matrix',1999,8160,'R','Action, Sci-Fi','A computer hacker discovers that his life is nothing more than an elaborate simulation run by an evil AI.','tt0133093','603-the-matrix',1,1,'The_Matrix'),
 (2,'movie','Liger',2021,8400,'PG-13','Action, Drama, Romance','A story about martial arts, dreams and star crossed lovers. Liger is an MMA fighter who trains hard and rises up the ranks with one goal in mind, to fight like his idol, world renowned MMA fighter Mark Anderson and get noticed by him.','tt4435072','787163',2,2,'Liger'),
 (3,'movie','Inception',2010,8880,'PG-13','Action, Adventure, Sci-Fi','A thief who steals corporate secrets through the use of dream-sharing technology is given the inverse task of planting an idea into the mind of a C.E.O.','tt1375666','27205-inception',3,1,'Inception'),
 (4,'movie','The Dark Knight',2008,9120,'PG-13','Action, Crime, Drama','When the menace known as the Joker wreaks havoc and chaos on the people of Gotham, Batman must accept one of the greatest psychological and physical tests of his ability to fight injustice.','tt0468569','155-the-dark-knight',4,1,'The_Dark_Knight'),
 (5,'movie','Interstellar',2014,10140,'PG-13','Adventure, Drama, Sci-Fi','A team of explorers travel through a wormhole in space in an attempt to ensure humanity''s survival.','tt0816692','157336-interstellar',5,2,'Interstellar_(film)'),
 (6,'movie','Pulp Fiction',1994,9240,'R','Crime, Drama','The lives of two mob hitmen, a boxer, a gangster and his wife, and a pair of diner bandits intertwine in four tales of violence and redemption.','tt0110912','680-pulp-fiction',6,1,'Pulp_Fiction'),
 (7,'movie','The Shawshank Redemption',1994,8520,'R','Drama','Over the course of several years, two convicts form a friendship, seeking consolation and, eventually, redemption through basic compassion.','tt0111161','278-the-shawshank-redemption',7,2,'The_Shawshank_Redemption'),
 (8,'movie','Fight Club',1999,8340,'R','Drama','An insomniac office worker and a devil-may-care soap maker form an underground fight club that evolves into much more.','tt0137523','550-fight-club',8,1,'Fight_Club'),
 (9,'movie','Forrest Gump',1994,8520,'PG-13','Drama, Romance','The history of the United States from the 1950s to the ''70s unfolds from the perspective of an Alabama man with an IQ of 75, who yearns to be reunited with his childhood sweetheart.','tt0109830','13-forrest-gump',9,3,'Forrest_Gump'),
 (10,'movie','The Godfather',1972,10500,'R','Crime, Drama','The aging patriarch of an organized crime dynasty in postwar New York City transfers control of his clandestine empire to his reluctant youngest son.','tt0068646','238-the-godfather',10,1,'The_Godfather'),
 (11,'movie','Goodfellas',1990,8700,'R','Biography, Crime, Drama','The story of Henry Hill and his life in the mob, covering his relationship with his wife Karen Hill and his mob partners Jimmy Conway and Tommy DeVito.','tt0099685','769-goodfellas',11,1,'Goodfellas'),
 (12,'movie','Spirited Away',2001,7500,'PG','Animation, Adventure, Family','During her family''s move to the suburbs, a sullen 10-year-old girl wanders into a world ruled by gods, witches, and spirits, and where humans are changed into beasts.','tt0245429','129-spirited-away',12,2,'Spirited_Away'),
 (13,'movie','Parasite',2019,7920,'R','Drama, Thriller','Greed and class discrimination threaten the newly formed symbiotic relationship between the wealthy Park family and the destitute Kim clan.','tt6751668','496243-parasite',13,3,'Parasite_(2019_film)'),
 (14,'movie','Gladiator',2000,9300,'R','Action, Adventure, Drama','A former Roman General sets out to exact vengeance against the corrupt emperor who murdered his family and sent him into slavery.','tt0172495','98-gladiator',14,2,'Gladiator_(2000_film)'),
 (15,'movie','The Prestige',2006,7800,'PG-13','Drama, Mystery, Sci-Fi','After a tragic accident, two stage magicians in 1890s London engage in a battle to create the ultimate illusion while sacrificing everything they have to outwit each other.','tt0482571','1124-the-prestige',15,1,'The_Prestige_(film)'),
 (16,'movie','Whiplash',2014,6360,'R','Drama, Music','A promising young drummer enrolls at a cut-throat music conservatory where his dreams of greatness are mentored by an instructor who will stop at nothing to realize a student''s potential.','tt2582802','244786-whiplash',16,3,'Whiplash_(2014_film)'),
 (17,'movie','The Departed',2006,9060,'R','Crime, Drama, Thriller','An undercover cop and a mole in the police attempt to identify each other while infiltrating an Irish gang in South Boston.','tt0407887','1422-the-departed',17,1,'The_Departed'),
 (18,'movie','Blade Runner 2049',2017,9840,'R','Action, Drama, Mystery','Young Blade Runner K''s discovery of a long-buried secret leads him to track down former Blade Runner Rick Deckard, who''s been missing for thirty years.','tt1856101','335984-blade-runner-2049',18,2,'Blade_Runner_2049'),
